You are the final independent editor of a literary translation Review Desk.

For every proposed fix in every chunk, decide whether that exact replacement
should be applied to the current Final translation.

Use the Source as the ground truth. Compare the Draft and current Final only to
understand context and whether the proposed fix improves fidelity, terminology,
grammar, register, and literary readability.

Apply a fix only when the proposed replacement is clearly better and supported
by the Source. Keep the current Final when the proposal is unsupported,
unnecessary, stylistically worse, changes meaning, or is uncertain. Judge every
issue independently. Do not rewrite any text and do not invent another option.

Return JSON only, with exactly this shape:
{
  "decisions": [
    {
      "chunk_index": 0,
      "choices": [
        {
          "issue_index": 0,
          "apply": true,
          "reason": "One concise reason grounded in this chunk."
        }
      ]
    }
  ]
}

Return every supplied chunk_index exactly once and every issue_index for that
chunk exactly once. apply must be a JSON boolean. Keep reasons concise.

REVIEW CASES:
[
  {
    "chunk_index": 1,
    "revision": 2,
    "source": "Mr Dursley was the director of a firm called Grunnings, which made drills. The Dursleys had everything they wanted, but they also had a secret. Mrs Potter was Mrs Dursley's sister, and they had not met for several years.",
    "draft": "Мистер Дурсли был директором фирмы Grunnings, которая делала свёрла.",
    "final": "Мистер Дурсль был директором фирмы «Граннингс», которая выпускала дрели.",
    "issues": [
      {
        "issue_index": 0,
        "span": "выпускала",
        "replacement": "производила",
        "type": "mistranslation",
        "severity": "major"
      }
    ]
  }
]

"""The app has no login, so who can reach it is the whole of its access control."""

import pytest

import translator as app_module


@pytest.fixture
def client(tmp_path, monkeypatch):
    monkeypatch.setattr(app_module, 'DB_PATH', str(tmp_path / 'translations.db'))
    monkeypatch.delenv('HOST', raising=False)
    app_module.init_db()
    app_module.app.config.update(TESTING=True)
    return app_module.app.test_client()


def test_the_server_listens_on_this_computer_unless_told_otherwise(monkeypatch):
    monkeypatch.delenv('HOST', raising=False)
    assert app_module.bind_host() == '127.0.0.1'

    monkeypatch.setenv('HOST', '0.0.0.0')
    assert app_module.bind_host() == '0.0.0.0'


@pytest.mark.parametrize('base_url', [
    'http://localhost:5001', 'http://127.0.0.1:5001', 'http://[::1]:5001',
])
def test_the_interface_reaches_its_own_server(client, base_url):
    assert client.get('/translations', base_url=base_url).status_code == 200
    # What the page's own fetch() sends on a POST or a DELETE.
    assert client.get(
        '/translations', base_url=base_url, headers={'Origin': base_url},
    ).status_code == 200


def test_another_sites_page_cannot_use_the_api(client):
    """A page on any site can send a request to localhost from the user's own
    browser. Deleting a job needs no response to be read, so withholding the
    CORS headers alone would not have stopped it."""
    refused = client.delete(
        '/translations/1', base_url='http://localhost:5001',
        headers={'Origin': 'https://example.com'},
    )

    assert refused.status_code == 403
    assert refused.get_json() == {'error': 'Cross-origin requests are not accepted'}
    assert 'Access-Control-Allow-Origin' not in refused.headers


def test_a_domain_pointed_at_this_computer_is_refused(client):
    """DNS rebinding: the attacker's own domain resolves to 127.0.0.1, so its
    Origin and Host agree with each other and only the name gives it away."""
    refused = client.get(
        '/translations', base_url='http://attacker.example:5001',
        headers={'Origin': 'http://attacker.example:5001'},
    )

    assert refused.status_code == 403
    assert refused.get_json() == {'error': 'This app only answers on this computer'}


def test_opening_the_app_to_the_network_is_an_explicit_choice(client, monkeypatch):
    monkeypatch.setenv('HOST', '0.0.0.0')
    by_address = 'http://192.168.1.20:5001'

    assert client.get('/translations', base_url=by_address).status_code == 200
    assert client.get(
        '/translations', base_url=by_address, headers={'Origin': by_address},
    ).status_code == 200
    # Still not for other sites' pages.
    assert client.get(
        '/translations', base_url=by_address, headers={'Origin': 'https://example.com'},
    ).status_code == 403


def test_no_cross_origin_headers_are_sent(client):
    response = client.get('/translations', headers={'Origin': 'http://localhost'})

    assert 'Access-Control-Allow-Origin' not in response.headers

from pathlib import Path

import pytest

import translator as app_module
from translator import GlossaryTerm, TerminologyManager


def test_parses_arrow_and_tsv_formats():
    manager = TerminologyManager.from_text(
        """
        Mr. Darcy => мистер Дарси | exact
        machine learning\tmaschinelles Lernen\tinflectable
        Home => Heimat
        """
    )

    assert manager.terms == [
        GlossaryTerm("Mr. Darcy", "мистер Дарси", "exact"),
        GlossaryTerm("machine learning", "maschinelles Lernen", "inflectable"),
        GlossaryTerm("Home", "Heimat", "inflectable"),
    ]


def test_a_note_after_the_mode_is_the_authors_own_annotation():
    """The reason the note exists: a rendering alone cannot say which of two
    gendered forms a name takes, and nothing in the source always settles it."""
    manager = TerminologyManager.from_text(
        "Rom => Rom | inflectable {c'est un garçon de huit ans}"
    )

    assert manager.terms == [
        GlossaryTerm("Rom", "Rom", "inflectable", "c'est un garçon de huit ans"),
    ]


def test_a_note_may_hold_the_delimiters_the_entry_itself_uses():
    """A note is prose. It must not have to avoid `=>` or `|` to survive."""
    manager = TerminologyManager.from_text(
        "a | b => c => d | preferred {x | y => z}"
    )

    assert manager.terms == [
        GlossaryTerm("a | b", "c => d", "preferred", "x | y => z"),
    ]


def test_a_note_also_follows_a_tab_separated_row():
    manager = TerminologyManager.from_text(
        "machine learning\tmaschinelles Lernen\tinflectable\t{masculine}"
    )

    assert manager.terms == [
        GlossaryTerm(
            "machine learning", "maschinelles Lernen", "inflectable", "masculine",
        ),
    ]


def test_an_entry_without_a_note_still_parses_exactly_as_before():
    assert TerminologyManager.from_text(
        "Rom => Rom | inflectable\nRomel => Romel\n"
    ).terms == [
        GlossaryTerm("Rom", "Rom", "inflectable"),
        GlossaryTerm("Romel", "Romel", "inflectable"),
    ]


def test_a_malformed_note_is_rejected_rather_than_read_as_a_mode():
    """Without this the note is swallowed into the mode and the entry is
    silently rejected, or worse, accepted as a mode nobody can enforce."""
    for text, message in (
        ("Rom => Rom | inflectable {}", "the note is empty"),
        ("Rom => Rom | inflectable {a boy", "unbalanced brace"),
        ("Rom => Rom | inflectable {a boy} and more", "unbalanced brace"),
        ("Rom => Rom | inflectable {" + "x" * 201 + "}", "note exceeds"),
    ):
        with pytest.raises(ValueError, match=message):
            TerminologyManager.from_text(text)


def test_a_note_survives_the_round_trip_through_the_text_format():
    """Every place that refills the textarea from stored terms goes through
    this, so a note written once is not lost on the next reopen."""
    line = TerminologyManager.format_line(
        "Rom", "Rom", "inflectable", "c'est un garçon",
    )

    assert line == "Rom => Rom | inflectable {c'est un garçon}"
    assert TerminologyManager.from_text(line).terms == [
        GlossaryTerm("Rom", "Rom", "inflectable", "c'est un garçon"),
    ]


def test_the_browser_parses_notes_by_the_same_rules():
    """The editor validates in JavaScript, before anything is uploaded, and
    there is no JS test runner here. If the two drift, the status line calls a
    perfectly good entry malformed — or worse, calls a broken one valid — and
    the author has no way to tell which parser Start will use."""
    index_html = (
        Path(app_module.__file__).parent / 'static' / 'index.html'
    ).read_text(encoding='utf-8')

    assert "const GLOSSARY_NOTE_SUFFIX = /\\{([^{}]*)\\}\\s*$/;" in index_html
    assert 'const GLOSSARY_MAX_NOTE_LENGTH = 200;' in index_html
    assert "'the note is empty'" in index_html
    assert "'an unbalanced brace" in index_html
    assert 'a note exceeds ${GLOSSARY_MAX_NOTE_LENGTH} characters' in index_html


def test_an_entry_with_no_note_is_formatted_exactly_as_it_was():
    assert TerminologyManager.format_line("Rom", "Rom", "inflectable") == (
        "Rom => Rom | inflectable"
    )


def test_omitted_mode_defaults_to_inflectable_for_arrow_and_tsv_formats():
    manager = TerminologyManager.from_text(
        "home => дом\nmachine learning\tмашинное обучение"
    )

    assert manager.terms == [
        GlossaryTerm("home", "дом", "inflectable"),
        GlossaryTerm("machine learning", "машинное обучение", "inflectable"),
    ]


def test_relevance_is_case_insensitive_and_supports_cjk():
    manager = TerminologyManager.from_text(
        """
        ALICE => Алиса | exact
        人工知能 => artificial intelligence | exact
        """
    )

    assert [term.source for term in manager.relevant_terms("Alice met Bob.")] == [
        "ALICE"
    ]
    assert [term.source for term in manager.relevant_terms("人工知能の研究")] == [
        "人工知能"
    ]


def test_exact_violations_only_check_relevant_exact_terms():
    manager = TerminologyManager.from_text(
        """
        garden => сад | exact
        house => дом | preferred
        absent => отсутствует | exact
        """
    )

    assert manager.exact_violations("The garden and house.", "Сад и жилище.") == []
    assert manager.exact_violations("The garden and house.", "Двор и жилище.") == [
        {"source": "garden", "required_target": "сад"}
    ]


def test_exact_terms_replace_only_literal_source_leaks():
    manager = TerminologyManager.from_text(
        "Dursley => Дурсль | exact\nHome => дом | inflectable"
    )

    translated, replacements = manager.enforce_exact_source_forms(
        "Dursley arrived. The Dursleys stayed. Home remained untranslated."
    )

    assert translated == "Дурсль arrived. The Dursleys stayed. Home remained untranslated."
    assert replacements == [{"source": "Dursley", "target": "Дурсль", "count": 1}]


def test_exact_source_replacement_is_case_insensitive_but_respects_word_boundaries():
    manager = TerminologyManager.from_text("garden => сад | exact")

    translated, replacements = manager.enforce_exact_source_forms(
        "GARDEN, garden; gardener; gardens."
    )

    assert translated == "сад, сад; gardener; gardens."
    assert replacements == [{"source": "garden", "target": "сад", "count": 2}]


def test_fingerprint_is_stable_but_changes_with_constraints():
    first = TerminologyManager.from_text(
        "cat => кот | exact\ndog => пёс | preferred"
    )
    reordered = TerminologyManager.from_text(
        "dog => пёс | preferred\ncat => кот | exact"
    )
    changed = TerminologyManager.from_text(
        "cat => кошка | exact\ndog => пёс | preferred"
    )

    assert first.fingerprint() == reordered.fingerprint()
    assert first.fingerprint() != changed.fingerprint()


def test_editing_only_a_note_retires_the_cached_chunks():
    """The note is part of the prompt, so it has to be part of the cache key.
    Without it, correcting a wrong note and pressing Continue would hand back
    the chunks translated under the note that was just fixed."""
    before = TerminologyManager.from_text("Rom => Rom | inflectable {a girl}")
    after = TerminologyManager.from_text("Rom => Rom | inflectable {a boy}")

    assert before.fingerprint() != after.fingerprint()

import json

import pytest

import frontier_review as review
from frontier_glossary import FrontierGlossaryError


CASES = [
    {
        'chunk_index': 1,
        'revision': 2,
        'source_language': 'English',
        'target_language': 'Russian',
        'source': 'The firm made drills.',
        'draft': 'Фирма делала свёрла.',
        'final': 'Фирма выпускала дрели.',
        'issues': [
            {
                'issue_index': 0,
                'span': 'выпускала',
                'replacement': 'производила',
                'type': 'mistranslation',
                'severity': 'major',
            },
            {
                'issue_index': 1,
                'span': 'дрели',
                'replacement': 'сверла',
                'type': 'style',
                'severity': 'minor',
            },
        ],
    },
]


class FakeResponse:
    ok = True
    status_code = 200

    def __init__(self, data):
        self.data = data

    def json(self):
        return self.data


class FakeClient:
    def __init__(self, data):
        self.data = data
        self.calls = []

    def post(self, url, **kwargs):
        self.calls.append((url, kwargs))
        return FakeResponse(self.data)


def _openai_response(decisions):
    return {
        'output': [{
            'type': 'message',
            'content': [{
                'type': 'output_text',
                'text': json.dumps({'decisions': decisions}, ensure_ascii=False),
            }],
        }],
    }


def test_openai_decides_every_issue_and_returns_a_deterministic_final():
    client = FakeClient(_openai_response([{
        'chunk_index': 1,
        'choices': [
            {
                'issue_index': 0,
                'apply': True,
                'reason': 'The source describes production.',
            },
            {
                'issue_index': 1,
                'apply': False,
                'reason': 'The current noun is the established rendering.',
            },
        ],
    }]))

    result = review.decide_review_cases(
        'openai',
        CASES,
        'session-key',
        'gpt-5.4-mini',
        client=client,
    )

    assert result.model == 'gpt-5.4-mini'
    assert result.decisions == [{
        'chunk_index': 1,
        'revision': 2,
        'text': 'Фирма производила дрели.',
        'applied_issue_indexes': [0],
        'kept_issue_indexes': [1],
        'choices': [
            {
                'issue_index': 0,
                'apply': True,
                'reason': 'The source describes production.',
            },
            {
                'issue_index': 1,
                'apply': False,
                'reason': 'The current noun is the established rendering.',
            },
        ],
    }]
    url, request = client.calls[0]
    assert url == 'https://api.openai.com/v1/responses'
    assert request['json']['store'] is False
    assert 'tools' not in request['json']
    assert request['timeout'] == (10, 600)


@pytest.mark.parametrize('decisions, message', [
    ([], 'did not decide every'),
    (
        [{
            'chunk_index': 1,
            'choices': [{
                'issue_index': 0,
                'apply': True,
                'reason': 'Supported.',
            }],
        }],
        'did not decide every issue',
    ),
    (
        [{
            'chunk_index': 1,
            'choices': [
                {
                    'issue_index': 0,
                    'apply': 'yes',
                    'reason': 'Supported.',
                },
                {
                    'issue_index': 1,
                    'apply': False,
                    'reason': 'Keep.',
                },
            ],
        }],
        'malformed choice',
    ),
])
def test_incomplete_or_malformed_cloud_decisions_are_rejected(decisions, message):
    client = FakeClient(_openai_response(decisions))

    with pytest.raises(FrontierGlossaryError, match=message):
        review.decide_review_cases(
            'openai',
            CASES,
            'session-key',
            client=client,
        )


def test_conflicting_applied_fixes_fail_without_returning_partial_text():
    cases = [{**CASES[0], 'issues': [
        {
            'issue_index': 0,
            'span': 'выпускала дрели',
            'replacement': 'производила сверла',
            'type': 'mistranslation',
            'severity': 'major',
        },
        {
            'issue_index': 1,
            'span': 'дрели',
            'replacement': 'инструменты',
            'type': 'style',
            'severity': 'minor',
        },
    ]}]
    client = FakeClient(_openai_response([{
        'chunk_index': 1,
        'choices': [
            {'issue_index': 0, 'apply': True, 'reason': 'First.'},
            {'issue_index': 1, 'apply': True, 'reason': 'Second.'},
        ],
    }]))

    with pytest.raises(FrontierGlossaryError, match='conflict'):
        review.decide_review_cases(
            'openai',
            cases,
            'session-key',
            client=client,
        )
